using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.VisualBasic;
using TabStudio.Debugging.Instrumentation;

namespace TabStudio.LiveTesting.Instrumentation;

/// <summary>
/// Recognizes the syntax trees Live Unit Testing never instruments or compares: trees without a file, such as
/// Visual Basic's My template, and generated files of either language.
/// </summary>
internal static class GeneratedSource
{
    private static readonly string[] VisualBasicSuffixes = [".g.vb", ".g.i.vb", ".designer.vb", ".generated.vb"];

    /// <summary>
    /// Whether a tree is generated: it has no file, its file name ends like the SDK's generated files (such as
    /// <c>obj/App.AssemblyInfo.g.vb</c>), or it starts with an <c>&lt;auto-generated&gt;</c> comment.
    /// </summary>
    /// <param name="tree">The tree.</param>
    /// <param name="cancellationToken">Cancels reading the tree.</param>
    public static bool IsGenerated(SyntaxTree tree, CancellationToken cancellationToken)
    {
        if (tree.FilePath.Length == 0)
        {
            return true;
        }

        if (!string.Equals(tree.Options.Language, LanguageNames.VisualBasic, StringComparison.Ordinal))
        {
            return GeneratedCode.IsGenerated(tree, cancellationToken);
        }

        var name = Path.GetFileName(tree.FilePath);
        if (VisualBasicSuffixes.Any(suffix => name.EndsWith(suffix, StringComparison.OrdinalIgnoreCase)))
        {
            return true;
        }

        return tree.GetRoot(cancellationToken).GetLeadingTrivia().Any(trivia =>
            trivia.IsKind(SyntaxKind.CommentTrivia) &&
            trivia.ToString().Contains("<auto-generated", StringComparison.OrdinalIgnoreCase));
    }
}
